/* Approved command sample, applied to the live application's original elements.
   This file changes presentation only. Every action is handled by the existing modules. */
(()=>{'use strict';
const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={gang:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 4a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 4v3"/>',swords:'<path d="m4 3 9 9m7-9-9 9M3 3l1 5 4-4M21 3l-1 5-4-4M8 15l-4 5m12-5 4 5M6 13l5 5m2-5 5-5"/>',flag:'<path d="M5 21V3m0 1c4-4 9 4 14 0v10c-5 4-10-4-14 0"/>',layers:'<path d="m12 3 10 6-10 6L2 9Zm-9 11 9 6 9-6M3 18l9 5 9-5"/>',arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>',shield:'<path d="m12 2 9 4v7c0 5-9 9-9 9s-9-4-9-9V6Z"/><path d="m8 12 3 3 5-6"/>',map:'<path d="m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2Zm6-2v16m6-14v16"/>',bolt:'<path d="m13 2-9 12h7l-1 8 10-13h-7Z"/>',account:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',book:'<path d="M12 5v15M12 5C8 2 3 3 3 3v16s5-1 9 1c4-2 9-1 9-1V3s-5-1-9 2Z"/>'};
const icon=k=>`<svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">${icons[k]||icons.flag}</svg>`;
const pair=(en,ko)=>`<span data-i18n-en="${E(en)}" data-i18n-ko="${E(ko)}">${E(window.UKI18n?.language==='en'?en:ko)}</span>`;
const element=(tag,cls)=>{const n=document.createElement(tag);n.className=cls;return n};
function section(){if(data.view==='catalog')return 'catalog';if(['campaign','campaigns'].includes(data.view))return 'campaigns';if(data.view==='dashboard')return data.homeTab||'gangs';return 'gangs';}
function sidebar(main){
 const side=element('aside','cmd-sidebar');side.dataset.commandDecoration='shell';
 const brand=main.querySelector('.top-wordmark');if(brand){const text=brand.lastElementChild;if(text&&!text.classList.contains('top-emblem'))text.innerHTML='<strong>UNDERHIVE</strong><small>KOREA</small>';side.append(brand);}
 const label=element('div','cmd-workspace-label');label.innerHTML='WORKSPACE';label.setAttribute('aria-hidden','true');label.setAttribute('data-i18n-ignore','');side.append(label);
 let nav=main.querySelector('.home-tabs');if(!nav){nav=element('nav','tabs home-tabs');nav.innerHTML=`<button type="button" data-parity="home" data-value="gangs">${pair('Gangs','갱')}</button><button type="button" data-sk-action="home">${pair('Skirmish','스커미시')}</button><button type="button" data-parity="home" data-value="campaigns">${pair('Campaigns','캠페인')}</button><button type="button" data-parity="home" data-value="catalog">${pair('Custom','커스텀')}</button>`;}nav.classList.add('cmd-nav');nav.setAttribute('aria-label',window.UKI18n?.language==='en'?'Main navigation':'주 메뉴');nav.setAttribute('role','navigation');
 for(const [index,b]of [...nav.children].entries()){const key=b.hasAttribute('data-sk-action')?'skirmishes':b.dataset.value;b.classList.toggle('active',key===section());if(key===section())b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');b.insertAdjacentHTML('afterbegin',icon(['gang','swords','flag','layers'][index]));}side.append(nav);
 const c=(data.campaigns||[]).find(c=>c.phase!=='Closed'&&c.id===data.selectedCampaign)||(data.campaigns||[]).find(c=>c.phase!=='Closed');if(c){const current=element('div','cmd-active-campaign');current.innerHTML=`<small>${pair('ACTIVE CAMPAIGN','진행 중인 캠페인')}</small><button type="button" data-open-campaign="${E(c.id)}"><i aria-hidden="true"></i><span data-user-text>${E(c.name)}<small>${E(c.edition)}</small></span>${icon('arrow')}</button>`;side.append(current);}
 const bottom=element('div','cmd-sidebar-bottom'),account=window.AccountParity?.account;bottom.innerHTML=`<a class="cmd-handbook" href="/chronicle.html">${icon('book')}${pair('Necromunda chronicle','네크로문다 연대기')}${icon('arrow')}</a><button type="button" class="cmd-account" data-account-action="open">${icon('account')}<span>${account?'<strong data-user-text>'+E(account.username)+'</strong>':pair('Sign in / Account','로그인·계정')}<small>${pair('Account & saved records','계정·저장 기록')}</small></span>${icon('shield')}</button>`;side.append(bottom);main.prepend(side);
 const top=main.querySelector('.topbar'),crumb=main.querySelector('.crumb');if(top&&crumb)top.prepend(crumb);
}
function welcome(main){const node=main.querySelector('.home-welcome');if(!node)return;const key=section(),titles={gangs:['My gangs','나의 갱','GANG DOSSIERS'],campaigns:['Campaign command','캠페인 지휘소','ARBITRATOR COMMAND'],skirmishes:['Skirmish','스커미시','QUICK PLAY'],catalog:['Custom assets','커스텀','PERSONAL ARCHIVE']},[en,ko,eyebrow]=titles[key]||titles.gangs;const h=node.querySelector('h1');if(h){h.innerHTML=pair(en,ko);h.removeAttribute('data-i18n-ko');h.removeAttribute('data-i18n-en');}const k=node.querySelector('.uk-hero-eyebrow');if(k){k.textContent=eyebrow;k.setAttribute('aria-hidden','true');}node.classList.add('cmd-page-heading');}
function homeCards(main){for(const card of main.querySelectorAll('.home-list-card')){const g=data.gangs.find(g=>g.id===card.querySelector('[data-open-gang]')?.dataset.openGang);if(!g)continue;card.dataset.commandGang=g.id;const type=window.MMVerifiedRules?.gangType(g)||window.MMGang?.findGangType(g),mark=element('small','cmd-card-kicker');mark.textContent=type?.name||g.faction||'';mark.setAttribute('data-user-text','');card.querySelector('.home-card-main h3')?.prepend(mark);const footer=element('div','cmd-gang-card-footer');footer.innerHTML='<span>'+pair('Credits','크레딧')+' <strong>'+E(new Intl.NumberFormat('en-US').format(Number(g.credits)||0))+'</strong></span><button type="button" data-command-open-gang="'+E(g.id)+'">'+pair('View roster','로스터 보기')+icon('arrow')+'</button>';card.append(footer);}}
function campaignPresentation(main){
 const root=main.querySelector('.cp-campaign-page');if(!root||data.campaignTab==='session-detail')return;const c=campaign();if(!c)return;
 const header=root.querySelector('.cp-campaign-header'),tabs=root.querySelector(':scope>.tabs');let hero;
 if(header){header.classList.add('cmd-campaign-record');hero=element('div','cmd-campaign-hero');if(tabs)root.insertBefore(header,tabs);const copy=element('div','cmd-campaign-copy'),cycle=header.querySelector('.csp-panel'),facts=header.querySelector('.entity-facts');const kicker=element('div','cmd-hero-kicker');kicker.innerHTML=`${pair('CAMPAIGN COMMAND','캠페인 지휘소')}<span>${E(c.edition)}</span>`;copy.append(kicker);for(const n of [...header.children])if(n!==cycle&&n!==facts)copy.append(n);hero.append(copy);const tools=element('details','cmd-campaign-tools');tools.innerHTML='<summary>'+pair('Campaign tools','운영 설정')+'</summary><div class="cmd-tools-panel"></div>';const panel=tools.lastElementChild;for(const n of [...copy.querySelectorAll(':scope>.entity-tools,:scope>.enroll-campaign-actions,:scope>.ctp-launch')])panel.append(n);const head=copy.querySelector('.entity-head');if(head)for(const n of [...head.children])if(!n.matches('.entity-title'))panel.append(n);if(panel.children.length)copy.insertBefore(tools,copy.children[1]||null);if(cycle){cycle.classList.add('cmd-cycle-control');hero.append(cycle);}const gs=(c.members||[]).map(m=>data.gangs.find(g=>g.id===m.gangId)).filter(Boolean),g=gs[0],src=g&&window.MMGangPortrait?.imageFor(g);if(c.image||src){const image=element('img','cmd-hero-art');image.src=c.image||src;image.alt='';image.setAttribute('aria-hidden','true');hero.prepend(image);}header.append(hero);if(facts){facts.classList.add('cmd-summary-strip');[...facts.children].forEach((n,index)=>{n.insertAdjacentHTML('afterbegin',icon(['gang','map','flag','swords'][index]));});header.append(facts);}}

 const console=root.querySelector('.ca-console');if(console){console.classList.add('cmd-command-panel');const modules=console.querySelector('.ca-modules');if(modules){const grid=element('div','cmd-command-grid'),aside=element('aside','cmd-next-action');aside.innerHTML=`<span class="cmd-next-icon">${icon('bolt')}</span><small data-i18n-ignore>YOUR NEXT MOVE</small><h2>${pair('Continue the campaign','캠페인을 진행하세요')}</h2><p>${pair('Open the next available action for the current campaign.','현재 캠페인에서 필요한 작업을 이어서 진행하세요.')}</p><button type="button" class="btn primary" data-command-next>${pair('Continue','다음 작업 열기')}${icon('arrow')}</button>`;modules.before(grid);grid.append(modules,aside);const battle=modules.querySelector('[data-ca-section="battle"]');if(battle)battle.open=true;const challenge=modules.querySelector('[data-ca-section=challenges]');if(challenge)challenge.open=false;syncNext(root,aside);if(hero){const mobile=element('div','cmd-mobile-next');mobile.innerHTML=aside.querySelector('[data-command-next]').outerHTML;hero.append(mobile);}}
 for(const row of console.querySelectorAll('.ca-preparation>article')){const sid=row.querySelector('[data-ca-id]')?.dataset.caId,s=(c.sessions||[]).find(s=>s.id===sid);if(!s)continue;const parties=element('div','cmd-battle-parties');for(const p of s.participants||[]){const g=data.gangs.find(g=>g.id===p.gangId);if(!g)continue;const src=window.MMGangPortrait?.imageFor(g),part=element('div','cmd-battle-party');if(src){const img=document.createElement('img');img.src=src;img.alt='';part.append(img);}const name=document.createElement('strong');name.textContent=g.name;name.setAttribute('data-user-text','');part.append(name);parties.append(part);}row.prepend(parties);}
 }
}
function nextSource(root){const selectors=['[data-ca-module="battle"][data-ca-action="settle"]','[data-ca-action="result"]','[data-ca-action="start"]','[data-ca-action="auto"]','[data-ca-module="preparation"][data-ca-action="new"]','[data-ca-action="new"]','[data-campaign-schedule="advance"]'];for(const selector of selectors){const b=[...root.querySelectorAll(selector)].find(b=>!b.disabled&&!b.closest('[hidden]'));if(b)return b;}return null;}
function syncNext(root,aside){const source=nextSource(root),button=aside.querySelector('[data-command-next]');button.disabled=!source;if(source){button.innerHTML=source.innerHTML+icon('arrow');const h=aside.querySelector('h2');h.innerHTML=source.innerHTML;}}
function refresh(){const main=document.querySelector('#app .main');if(!main||main.dataset.commandReady)return;main.dataset.commandReady='true';document.documentElement.classList.add('command-ui');sidebar(main);welcome(main);homeCards(main);campaignPresentation(main);window.UKI18n?.refresh(main);}
window.addEventListener('click',event=>{const roster=event.target.closest?.('[data-command-open-gang]');if(roster){roster.closest('.home-list-card')?.querySelector('.home-card-main[data-open-gang]')?.click();return;}const button=event.target.closest?.('[data-command-next]');if(!button||button.disabled)return;const root=button.closest('.cp-campaign-page'),source=root&&nextSource(root);if(!source)return;const details=source.closest('details');if(details)details.open=true;source.click();});
document.addEventListener('keydown',event=>{if(event.key!=='Escape'||document.querySelector('.modal-bg,.mmrr-overlay'))return;const menu=document.querySelector('.cmd-campaign-tools[open]');if(menu){menu.open=false;menu.querySelector('summary')?.focus();}});
document.addEventListener('pointerdown',event=>{if(document.querySelector('.modal-bg,.mmrr-overlay'))return;for(const menu of document.querySelectorAll('.cmd-campaign-tools[open]'))if(!menu.contains(event.target))menu.open=false;});
// A subtle highlight is decorative, stops on pointer exit, and respects reduced motion.
document.addEventListener('pointermove',event=>{if(event.pointerType!=='mouse'||window.matchMedia?.('(prefers-reduced-motion: reduce)').matches)return;const card=event.target.closest?.('.home-list-card,.cmd-campaign-hero');if(!card)return;const r=card.getBoundingClientRect();card.style.setProperty('--cmd-pointer-x',Math.round(event.clientX-r.left)+'px');card.style.setProperty('--cmd-pointer-y',Math.round(event.clientY-r.top)+'px');});
const previous=render;render=function(){const result=previous.apply(this,arguments);refresh();return result;};window.MMCommandInterface={refresh,closeForCapture(trigger){const menu=trigger.closest('.cmd-campaign-tools');if(!menu?.open)return()=>{};menu.open=false;return()=>{if(menu.isConnected)menu.querySelector('summary')?.focus()};}};refresh();
})();
